def pi(n):
    primes = []
    for i in range(2, n + 1):
        for p in primes:
            if i % p == 0:
                break
        else:
            primes.append(i)
    return len(primes)

def count_pairs(n):
    g = 2023
    L = 1
    import math
    for i in range(1, n + 1):
        L *= i

    if L % g != 0:
        return 0

    L_over_g = L // g
    # Find distinct prime factors of L_over_g
    distinct_primes = 0
    temp = L_over_g
    d = 2
    while d * d <= temp:
        if temp % d == 0:
            distinct_primes += 1
            while temp % d == 0:
                temp //= d
        d += 1
    if temp > 1:
        distinct_primes += 1

    return 2**distinct_primes

# However, for large n, L will be huge.
# We can use the property: k = number of distinct prime factors of n! / 2023.
def get_k(n):
    # 2023 = 7 * 17^2
    # Primes in n!: primes p <= n.
    # Prime p divides n!/2023 if v_p(n!) > v_p(2023).
    # v_7(2023) = 1, v_17(2023) = 2, others 0.

    import sympy
    primes_le_n = list(sympy.primerange(2, n + 1))
    k = 0
    for p in primes_le_n:
        # Calculate v_p(n!)
        vp_n_factorial = 0
        pp = p
        while pp <= n:
            vp_n_factorial += n // pp
            pp *= p

        # v_p(2023)
        vp_2023 = 0
        if p == 7:
            vp_2023 = 1
        elif p == 17:
            vp_2023 = 2

        if vp_n_factorial > vp_2023:
            k += 1

    # Check if 2023 divides n!
    # 2023 = 7 * 17^2
    # We need v_7(n!) >= 1 and v_17(n!) >= 2.
    # v_7(n!) >= 1 for n >= 7.
    # v_17(n!) >= 2 for n >= 34.
    if n < 34:
        return -1 # meaning number of pairs is 0

    return k

results = []
for n in range(1, 100):
    k = get_k(n)
    if k == -1:
        num_pairs = 0
    else:
        num_pairs = 2**k
    results.append((n, num_pairs))

valid_n = [n for n, count in results if count <= 4000]
print("Valid n:", valid_n)
print("Sum of valid n:", sum(valid_n))
print("Sum of valid n >= 34:", sum([n for n in valid_n if n >= 34]))
